private fun normalizeArabicAnswer(value:String)=value.replace(Regex("[\\u064B-\\u065F\\u0670\\u0640]"),"").replace(Regex("[\\s،؛,.!?؟]"),"").trim()
@Composable fun ConjugationTrainerScreen(repository:BookRepository,progress:ProgressStore,reviewOnly:Boolean,back:()->Unit){var key by remember{mutableIntStateOf(0)};val all=remember(key,reviewOnly){repository.conjugationQuestions(if(reviewOnly)Int.MAX_VALUE else 240)};val qs=remember(all,reviewOnly,progress.conjugationWrong){if(reviewOnly)all.filter{progress.conjugationWrong.contains(it.id)}else all.take(20)};if(qs.isEmpty()){EmptyStudyState(if(reviewOnly)"Ошибок для повторения нет" else "Таблицы спряжения не найдены",if(reviewOnly)"Все отмеченные формы сейчас закрыты." else "Тренажёр использует только распознанные таблицы из раздела морфологии.",back);return};var index by remember(key){mutableIntStateOf(0)};var answer by remember(key,index){mutableStateOf("")};var checked by remember(key,index){mutableStateOf(false)};var correctSession by remember(key){mutableIntStateOf(0)};if(index>=qs.size){val percent=((correctSession*100f)/qs.size).toInt();Column(Modifier.fillMaxSize().padding(22.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Outlined.CheckCircle,null,tint=MaterialTheme.colorScheme.secondary,modifier=Modifier.size(38.dp));Spacer(Modifier.height(12.dp));Text("Тренировка завершена",style=MaterialTheme.typography.titleLarge,color=CardHeadlineBrown);Text("$correctSession из ${qs.size} · $percent%",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(18.dp));Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){OutlinedButton(onClick=back,modifier=Modifier.weight(1f)){Text("Назад")};Button(onClick={key++},modifier=Modifier.weight(1f)){Icon(Icons.Outlined.Refresh,null);Spacer(Modifier.width(5.dp));Text("Ещё раз")}}};return};val q=qs[index];val expected=normalizeArabicAnswer(q.answer);val given=normalizeArabicAnswer(answer);val correct=checked&&given==expected;Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(8.dp),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=back){Icon(Icons.Outlined.ArrowBack,"Назад")};Column(Modifier.weight(1f)){Kicker(if(reviewOnly)"Работа над ошибками" else "Спряжение");Text("${index+1} из ${qs.size}",style=MaterialTheme.typography.titleSmall)};Text("${progress.conjugationAccuracy()}%",color=MaterialTheme.colorScheme.secondary)};LinearProgressIndicator(progress=(index+1f)/qs.size,modifier=Modifier.fillMaxWidth());Column(Modifier.fillMaxSize().padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){ElevatedCard(Modifier.fillMaxWidth(),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(18.dp)){Kicker(q.sectionTitle);Text(q.personLabel,style=MaterialTheme.typography.titleMedium,color=CardHeadlineBrown);Text(q.numberLabel,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(14.dp));Text("Введи арабскую форму по памяти.")}};CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl){OutlinedTextField(value=answer,onValueChange={if(!checked)answer=it},modifier=Modifier.fillMaxWidth(),textStyle=TextStyle(fontFamily=arabicFont(progress.settings),fontSize=(24f*progress.settings.arabicScale).sp,textDirection=TextDirection.Rtl,textAlign=TextAlign.End),placeholder={Text("اكتب الجواب")},singleLine=true,enabled=!checked,shape=RoundedCornerShape(18.dp),keyboardOptions=KeyboardOptions(imeAction=ImeAction.Done))};if(!checked){Button(onClick={checked=true;val hit=given.isNotBlank()&&given==expected;if(hit)correctSession++;progress.recordConjugation(q.id,hit)},enabled=answer.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text("Проверить")};TextButton(onClick={checked=true;progress.recordConjugation(q.id,false)},modifier=Modifier.align(Alignment.CenterHorizontally)){Text("Не помню — показать ответ")}}else{Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=if(correct)MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.errorContainer),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp)){Text(if(correct)"Верно" else "Правильная форма",style=MaterialTheme.typography.titleSmall,color=CardHeadlineBrown);CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl){Text(q.answer,Modifier.fillMaxWidth(),textAlign=TextAlign.End,style=TextStyle(fontFamily=arabicFont(progress.settings),fontSize=(26f*progress.settings.arabicScale).sp,lineHeight=(38f*progress.settings.arabicScale).sp,textDirection=TextDirection.Rtl,color=MaterialTheme.colorScheme.onSurface))}}};Button(onClick={index++;answer="";checked=false},modifier=Modifier.fillMaxWidth()){Text(if(index==qs.lastIndex)"Завершить" else "Следующая форма")}}}}}
